// js/sim/dns.js
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!MINI_IP.test(address)) throw new Error(`dns: invalid mini-IP address ${address}`);
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  const authoritative = new Map([['example.com', '10.1']]);
  const cache = new Map(); // name -> { name, target, expiresAtTick }
  let lookups = 0, cachedHits = 0, authoritativeHits? , nxResponses?...
  let lastLookup = null;
  function lookup(name, currentTick = 0) {
    lookups += 1;
    const entry = cache.get(name);
    if (entry && currentTick < entry.expiresAtTick) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { name, target: entry.target, status: 'HIT', source: address };
    }
    if (entry) { cache.delete(name); evictions += 1; } // expired entry never answers from the ledger
    const target = authoritative.get(name) ?? null;
    if (target === null) {
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { name, status: 'NX', target: null, source: address };
    }
    cache.set(name, { name, target, cachedAtTick: currentTick, expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, status: 'MISS', target, atTick: currentTick };
    return { name, target, status: 'MISS', source: address };
  }
  function snapshot(currentTick = 0) { evict expired; return { address, ttlTicks, lookups, cachedHits, misses, nx, authoritative: Object.fromEntries(authoritative), cache: [...] }; }
}
```

