const MINI_IP = /^\d+\.\d+$/;
export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress) || !MINI_IP.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP interface ${leftAddress} / ${rightAddress}`);
  }
  const subnetOf = (addr) => String(addr).split('.')[0];
  const leftSubnet = subnetOf(leftAddress);
  const rightSubnet = subnetOf(rightAddress);
  if (leftSubnet === rightSubnet) {
    throw new Error(`router: both interfaces sit on subnet ${leftSubnet} — two subnets required`);
  }
  let leftNetwork = null;
  let rightNetwork = null;
  let routed = 0;
  let lastFrame = null;

  function exitFor(frame) {
    const fromSubnet = subnetOf(frame.from);
    const toSubnet = subnetOf(frame.to);
    if (fromSubnet === leftSubnet && toSubnet === rightSubnet) return rightNetwork;
    if (fromSubnet === rightSubnet && toSubnet === leftSubnet) return leftNetwork;
    return null;
  }

  function mark(frame) {
    routed += 1;
    lastFrame = `router ${leftAddress} ⇄ ${rightAddress} forwarded ${frame.from} -> ${frame.to} (${frame.request})`;
  }

  return {
    get leftAddress() { return leftAddress; },
    get rightAddress() { return rightAddress; },
    get routed() { return routed; },
    attach(left, right) {
      if (!left || !right) throw new Error('router: attach needs both subnet networks');
      if (left.subnet !== leftSubnet || right.subnet !== rightSubnet) {
        throw new Error(`router: networks must be subnets ${leftSubnet} and ${rightSubnet}`);
      }
      leftNetwork = left;
      rightNetwork = right;
    },
    forward(frame) {
      const exit = exitFor(frame);
      if (!exit) throw new Error(`router: no route from ${subnetOf(frame.from)}.x to ${subnetOf(frame.to)}.x`);
      mark(frame);
      return exit.receiveRouted(frame);
    },
    forwardQueue(frame) {
      const exit = exitFor(frame);
      if (!exit) throw ...same;
      mark(frame);
      exit.enqueueRouted(frame);
    },
    snapshot() { return { leftAddress, rightAddress, routed, lastFrame }; },
  };
}
