const MINI_IP = /^\d+\.\d+$/;
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!MINI_IP.test(address)) throw new Error(`dns: invalid mini-IP address ${address}`);
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  // Stage 6a authoritative table: the LB VIP answers for example.com.
  // Stage 6b adds the CDN edge name on subnet 20.
  const authoritative = new Map([['example.com', '10.1']]);
  const cache = new Map();
  let lookups = 0, cachedHits = 0, misses = 0, nx = 0, evictions = 0;
  let lastLookup = null;

  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) { cache.delete(entry.name); evictions += 1; }
    }
  }

  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = cache.get(name);
    if (entry) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { name, status: 'HIT', target: entry.target, source: address };
    }
    // miss or expired: consult the authoritative table — the ledger never answers
    const target = authoritative.get(name) ?? null;
    if (target === null) {
      nx += 1;
      lastLookup = { name, status: 'NX', target: null, atTick: currentTick };
      return { name, status: 'NX', target: null, source: address };
    }
    misses += 1;
    cache.set(name, { name, target, cachedAtTick: currentTick, expiresAtTick: currentTick + ttlTicks });
