// DOCUMENTS: the Stage 6 component — an authoritative name table
// (example.com -> 10.1) fronted by a resolver cache with tick-based TTL,
// mirroring the Cache 10.20 ledger pattern. It is a real Map lookup on the
// request path, not a hit probability: entries carry
// cachedAtTick/expiresAtTick, an expired entry is dropped before it can
// answer, and lookups/cachedHits/misses/nx counters record what actually
// happened. Deterministic by construction: time arrives as the
// `currentTick` argument, never a clock.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration).
const MINI_IP = /^\d+\.\d+$/;

export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!MINI_IP.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  // Stage 6a authoritative table: the LoadBalancer VIP answers for
  // example.com; Stage 6b adds the CDN edge name on subnet 20.
  const authoritative = new Map([['example.com', '10.1']]);
  const cache = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let misses = 0;
  let nx = 0;
  let evictions = 0;
  let lastLookup = null;

  // An entry dies the moment the current tick reaches its expiry: cached at
  // tick T with ttlTicks = 300 means alive through tick T + 299.
  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) {
        cache.delete(entry.name);
        evictions += 1;
      }
    }
  }

  // CHECKS: a ledger HIT inside ttlTicks answers from the cache alone —
  // cachedHits increments and the authoritative table is not consulted.
  // A miss OR an expired entry consults the authoritative table; an expired
  // entry is dropped first, so it cannot answer from the ledger.
  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = cache.get(name);
    if (entry) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { name, status: 'HIT', target: entry.target, source: address };
    }
    const target = authoritative.get(name) ?? null;
    if (target === null) {
      // Unknown names never throw at the DNS layer: the browser renders the
      // NX answer; the fail-loud throw rule belongs to unregistered hosts.
      nx += 1;
      lastLookup = { name, status: 'NX', target: null, atTick: currentTick };
      return { name, status: 'NX', target: null, source: address };
    }
    misses += 1;
    cache.set(name, {
      name,
      target,
      cachedAtTick: currentTick,
      expiresAtTick: currentTick + ttlTicks,
    });
    lastLookup = { name, status: 'MISS', target, atTick: currentTick };
    return { name, status: 'MISS', target, source: address };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      misses,
      nx,
      evictions,
      lastLookup,
      authoritative: Object.fromEntries(authoritative),
      cache: [...cache.values()].map((e) => ({
        name: e.name,
        target: e.target,
        cachedAtTick: e.cachedAtTick,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    evictExpired,
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a cross-subnet Router with one
// interface per subnet (leftAddress on the 10.x side, rightAddress on the
// 20.x side). It joins the two Network instances via attach(); any frame
// whose source and destination sit on different subnets takes exactly one
// router hop (routed increments) and is delivered into the exit network.
// `isYou` and the rest of the frame ride through untouched.
//
// CHECKS: the constructor rejects an interface that is not a two-number
// mini-IP and two interfaces on the same subnet; forwarding without both
// networks attached, routing into a third subnet, or a frame that stays on
// the caller's own subnet fail loud.
const MINI_IP = /^\d+\.\d+$/;

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress) || !MINI_IP.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP interface ${leftAddress} / ${rightAddress}`);
  }
  const subnetOf = (addr) => String(addr).split('.')[0];
  const leftSubnet = subnetOf(leftAddress);
  const rightSubnet = subnetOf(rightAddress);
  if (leftSubnet === rightSubnet) {
    throw new Error(
      `router: both interfaces sit on subnet ${leftSubnet} — two different subnets required`,
    );
  }
  let leftNetwork = null;
  let rightNetwork = null;
  let routed = 0;
  let lastFrame = null;

  function exitFor(frame) {
    if (!leftNetwork || !rightNetwork) {
      throw new Error('router: no networks attached — call attach(left, right) first');
    }
    const fromSubnet = subnetOf(frame.from);
    const toSubnet = subnetOf(frame.to);
    if (fromSubnet === leftSubnet && toSubnet === rightSubnet) return rightNetwork;
    if (fromSubnet === rightSubnet && toSubnet === leftSubnet) return leftNetwork;
    throw new Error(
      `router: no route from subnet ${fromSubnet}.x to subnet ${toSubnet}.x (interfaces ${leftAddress} ⇄ ${rightAddress})`,
