  }

  function markRouted(frame) {
    routed += 1;
    lastFrame = `router ${leftAddress} ⇄ ${rightAddress} forwarded ${frame.from} -> ${frame.to} (${frame.request})`;
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },
    get routed() {
      return routed;
    },

    // Joins the two subnet networks; the networks' own subnets must match
    // the router's interfaces or the topology is miswired — fail loud.
    attach(left, right) {
      if (!left || !right) {
        throw new Error('router: attach needs both subnet networks');
      }
      if (left.subnet !== leftSubnet || right.subnet !== rightSubnet) {
        throw new Error(
          `router: attached networks must be subnets ${leftSubnet} and ${rightSubnet}`,
        );
      }
      leftNetwork = left;
      rightNetwork = right;
    },

    // A synchronous cross-subnet request: one router hop, then the exit
    // network delivers locally. routed counts completed forwards only.
    forward(frame) {
      const exit = exitFor(frame);
      const response = exit.receiveRouted(frame);
      markRouted(frame);
      return { ...frame, ...response };
    },

    // A queued cross-subnet request: one router hop into the exit network's
    // queue (used by the LB/enqueue path the same way).
    forwardQueue(frame) {
      const exit = exitFor(frame);
      exit.enqueueRouted(frame);
      markRouted(frame);
    },

    snapshot() {
      return { leftAddress, rightAddress, routed, lastFrame };
    },
  };
}

