// DOCUMENTS: pure presentation model — engine snapshot in, labels and bar
// geometry out. No DOM here: this is what the unit suite pins; panel.js and
// render.js own all DOM writes.
import { hasHost } from '../sim/host-path.js';
export const TICK_MS = 100;
const QUEUE_BAR_SATURATION = 20; // bar reads full at 20 queued requests
// Total hops per stage's trace shape (trace.js and engine.traceHop agree).
const TOTAL_HOPS = { 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 10 };

// The Stage 6 total branches on the run's host syntax: a hosted path pays
// 2 DNS hops (10 total), a host-less path keeps the Stage 5 count (8), and
// an unknown name ends at the browser's NX render (4). The NX decision
// reads the DNS component's actual authoritative table from the snapshot —
// the same table lookup() consults — so the panel never guesses.
export function totalHopsForSnapshot(snapshot = null) {
  const stage = snapshot?.stage ?? 1;
  if (stage !== 6) return TOTAL_HOPS[stage] ?? 4;
  const path = snapshot.trace?.path ?? '';
  if (!hasHost(path)) return 8;
  const host = String(path).split('/')[0];
  return snapshot.dns?.authoritative?.[host] ? 10 : 4;
}

