// One hop-status sentence per hop, in hop order, for each stage's trace
// shape: 4 hops in Stage 1 (emit, route, serve, render), 5 in Stage 2 (LB
// round-robin pick), 6 in Stage 3 (cache check, then response emit), 7 in
// Stage 4 (the database hop after the cache check), 8 in Stage 5 (the
// async queue story). Stage 6 branches on host syntax: host-less paths
// reuse the Stage 5 sentences byte-identical, hosted paths shift the
// Stage 5 story by exactly 2 DNS hops, unknown names render the NX story.
function dbOpPhrase(snapshot, t) {
  const db = snapshot.database ?? {};
  const primary = db.primaryAddress ?? '10.30';
  const replica = db.replicaAddress ?? '10.31';
  const lag = db.replicationLagTicks ?? 3;
  if (t.dbOp === 'WRITE') {
    return `Database WRITE @ Primary (${primary}) — replica lags ${lag}t`;
  }
  if (t.dbOp === 'SELECT' && t.dbStale) {
    return `Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`;
  }
  if (t.dbOp === 'SELECT') {
    return `Database SELECT @ Replica (${replica}) — fresh`;
  }
  return `Database SKIP — warm cache HIT (${snapshot.cache?.address ?? '10.20'})`;
}

// Stage 5's 8 sentences (also the Stage 6 host-less story byte-identical).
function stage5Sentences(snapshot, t, from, serverAddress) {
  const target = t.targetServer ?? '10.11';
  const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
  if (t.asyncJob) {
    return [
      `Hop 1/8: Browser (${from}) emits "${t.request}"`,
      `Hop 2/8: Network (10.x) routes to LoadBalancer (${serverAddress})`,
      `Hop 3/8: LoadBalancer (${serverAddress}) -> ${target} queue`,
      `Hop 4/8: WebServer (${target}) enqueues job to WorkerQueue (10.40)`,
      `Hop 5/8: WebServer (${target}) -> "202 Accepted"`,
      `Hop 6/8: Network delivers 202 response to ${from}`,
      `Hop 7/8: Browser (${from}) received and displayed 202 Accepted`,
      `Hop 8/8: Worker (${worker}) processed job and committed to Database (10.30)`,
    ];
  }
  // Requests served synchronously keep the Stage 4 cache/database story;
  // the worker does not see them, so the tail hop reads idle.
  return [
    `Hop 1/8: Browser (${from}) emits "${t.request}"`,
    `Hop 2/8: Network (10.x) routes to LoadBalancer (${serverAddress})`,
    `Hop 3/8: LoadBalancer (${serverAddress}) -> ${target} queue`,
    `Hop 4/8: ${dbOpPhrase(snapshot, t)}`,
    `Hop 5/8: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
    `Hop 6/8: Network delivers ${t.status} response to ${from}`,
    `Hop 7/8: Browser (${from}) received and displayed ${t.status}`,
    `Hop 8/8: Worker (${worker}) idle — no async jobs in this trace`,
  ];
}

// Stage 6 hosted: the Stage 5 story with exactly 2 DNS hops inserted at
// positions 2-3 and every later hop renumbered +2 (the /10 denominator).
function stage6HostedSentences(snapshot, t, from, serverAddress) {
  const target = t.targetServer ?? '10.11';
  const dnsAddr = snapshot.dns?.address ?? '10.60';
  const host = t.host ?? String(t.path ?? '').split('/')[0];
  const ans = t.dnsAnswer ?? null;
  const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
  const answerSentence = ans
    ? ans.status === 'NX'
      ? `Hop 3/10: DNS (${dnsAddr}) answers NX — no record for ${host}`
      : `Hop 3/10: DNS (${dnsAddr}) answers ${host} -> ${ans.target} (${ans.status})`
    : `Hop 3/10: DNS (${dnsAddr}) answers for ${host}`;
  return [
    `Hop 1/10: Browser (${from}) emits "${t.request}"`,
    `Hop 2/10: Browser (${from}) asks DNS (${dnsAddr}) for ${host}`,
    answerSentence,
    `Hop 4/10: Network (10.x) routes to LoadBalancer (${serverAddress})`,
    `Hop 5/10: LoadBalancer (${serverAddress}) -> ${target} queue`,
    t.asyncJob
      ? `Hop 6/10: WebServer (${target}) enqueues job to WorkerQueue (${snapshot.workerQueue?.address ?? '10.40'})`
      : `Hop 6/10: ${dbOpPhrase(snapshot, t)}`,
    t.asyncJob
      ? `Hop 7/10: WebServer (${target}) -> "${t.response}"`
      : `Hop 7/10: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
    `Hop 8/10: Network delivers ${t.status} response to ${from}`,
    `Hop 9/10: Browser (${from}) received and displayed ${t.status}`,
    t.asyncJob
      ? `Hop 10/10: Worker (${worker}) processed job and committed to Database (${snapshot.database?.primaryAddress ?? '10.30'})`
      : `Hop 10/10: Worker (${worker}) idle — no async jobs in this trace`,
  ];
}

// Stage 6 unknown name: DNS ask + NX answer, then the browser renders the
// NX card — the trace ends at 4 hops with no GET emitted.
function stage6NxSentences(snapshot, t, from) {
  const dnsAddr = snapshot.dns?.address ?? '10.60';
  const host = t.host ?? String(t.path ?? '').split('/')[0];
  return [
    `Hop 1/4: Browser (${from}) emits "${t.request}"`,
    `Hop 2/4: Browser (${from}) asks DNS (${dnsAddr}) for ${host}`,
    `Hop 3/4: DNS (${dnsAddr}) answers NX — no record for ${host}`,
    `Hop 4/4: Browser (${from}) renders NX — no GET emitted`,
  ];
}

function hopSentences(stage, snapshot, from, serverAddress) {
  const t = snapshot.trace ?? {};
  if (stage === 6) {
    const host = t.host ?? String(t.path ?? '').split('/')[0];
    if (host && snapshot.dns?.authoritative?.[host] === undefined) {
      return stage6NxSentences(snapshot, t, from);
    }
    if (host) return stage6HostedSentences(snapshot, t, from, serverAddress);
    return stage5Sentences(snapshot, t, from, serverAddress);
  }
  if (stage === 5) {
    return stage5Sentences(snapshot, t, from, serverAddress);
  }
  if (stage === 4) {
    const db = snapshot.database ?? null;
    const primary = db?.primaryAddress ?? '10.30';
    const replica = db?.replicaAddress ?? '10.31';
    const lag = db?.replicationLagTicks ?? 3;
    const dbSentence = t.dbOp === 'WRITE'
      ? `Hop 5/7: Database WRITE @ Primary (${primary}) — replica lags ${lag}t`
      : t.dbOp === 'SELECT' && t.dbStale
        ? `Hop 5/7: Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`
        : t.dbOp === 'SELECT'
          ? `Hop 5/7: Database SELECT @ Replica (${replica}) — fresh`
          : `Hop 5/7: Database SKIP — warm cache HIT (10.20)`;
    return [
      `Hop 1/7: Browser (${from}) emits "${t.request}"`,
      `Hop 2/7: Network (10.x) routes to LoadBalancer (${serverAddress})`,
      `Hop 3/7: LoadBalancer (${serverAddress}) -> ${target} queue`,
      `Hop 4/7: WebServer (${target}) checks Cache (10.20) — ${t.cacheStatus}`,
      dbSentence,
      `Hop 6/7: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
      `Hop 7/7: Browser (${from}) rendered ${t.status}`,
